const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm');
function harness(){const source=fs.readFileSync(path.join(__dirname,'../site-bridge.js'),'utf8'),start=source.indexOf(' async function saveCustomerSavedData('),end=source.indexOf(' async function changeCustomerAssignment(',start),calls=[];const context={lastRoster:[{id:'customer-a'}],lastRosterAt:Date.now(),Date,indexUntil:1,notifyOwner(){},id(value){if(!/^[a-zA-Z0-9:_-]{1,150}$/.test(String(value??'')))throw Error('Invalid identifier');return value;},api:async(...args)=>{calls.push(args);return {saved:true};}};vm.createContext(context);const save=vm.runInContext(source.slice(start,end)+';saveCustomerSavedData',context);return {save,calls};}
test('actual site bridge creates a saved website address without requiring a nonexistent record ID',async()=>{const h=harness();const result=await h.save('customer-a','address','',{operation:'create',confirmed:true,address:{address:'100 Example Street'}});assert.equal(result.saved,true);assert.equal(h.calls[0][0],'/api/admin/aco-studio/customers/customer-a/shipping-addresses');assert.equal(h.calls[0][1],'POST');});
test('actual site bridge targets the exact record for revision-checked deletion and rejects missing record IDs',async()=>{const h=harness(),revision='a'.repeat(64);await h.save('customer-a','payment','card-a',{operation:'delete',confirmed:true,expectedRevision:revision});assert.equal(h.calls[0][0],'/api/admin/aco-studio/customers/customer-a/payment-methods/card-a');assert.equal(h.calls[0][1],'DELETE');await assert.rejects(h.save('customer-a','payment','',{operation:'delete',confirmed:true,expectedRevision:revision}),/Invalid identifier/);assert.equal(h.calls.length,1);});
